    for (int i = 0; i < n; ++i) {
        long id = IdOf(a[i]);
        if (id < 0 || id >= n || (mask & (1u << id)) || !PayloadOk(a[i]))
            return false;
        mask |= 1u << id;
    }
    return true;
}

